OmniUiCard.stylingConfiguration:
{"customStyles":".serviceability-block-header .block-header > button{
 width: 100%;
 background-color: #F3F3F3;
 color: #181818;
}

.serviceability-total-umi_label{
 font-weight: 700;
 font-size: 12px;
}
.serviceability-total-umi_label .slds-popover__body{
 text-align: left !important;
 font-size: var(--slds-c-tooltip-font-size, var(--sds-c-tooltip-font-size, 0.75rem));
 font-weight: normal;
}
.serviceability-total-umi_pos_value,
.serviceability-total-umi_neg_value{
 font-weight: 590;
 font-size: 16px;
}
.serviceability-total-umi_pos_value{
 color: #027E46;
}

.serviceability-umi-category-title{
	font-weight: 590;
	font-size: 16px;
}

.serviceability-umi-table_income .tableHeadCell .slds-th__action,
.serviceability-umi-table_income .tableHeadCell .slds-th__action:hover{
 background: #C8E9E1 !important;
} 

.serviceability-umi-table_expense .tableHeadCell .slds-th__action,
.serviceability-umi-table_expense .tableHeadCell .slds-th__action:hover{
 background: #E2F6FD !important;
}

.serviceability-umi-table_debt .tableHeadCell .slds-th__action,
.serviceability-umi-table_debt .tableHeadCell .slds-th__action:hover{
 background: #FFE2D9 !important;
}

.serviceability-umi-table .tableRow:last-child{
 background:#F3F3F3 !important;
}

.serviceability-umi-table {
 color:#181818 !important;
}

.serviceability-umi-table .tableHeadCell, 
.serviceability-umi-table .tableRow:last-child{
 font-weight: 700 !important;
 font-size: 13px !important;
}

.serviceability-umi-table .slds-data-table-row-cell .dataTableCell{
 pointer-events: none
}
.serviceability-umi-table .slds-data-table-row-cell:nth-child(3) .dataTableCell,
.serviceability-umi-table .slds-data-table-row-cell:nth-child(4) .dataTableCell{
 display: flex;
 justify-content: right;
}

.serviceability-umi-table .slds-data-table-head-cell:nth-child(3) .slds-th__action,
.serviceability-umi-table .slds-data-table-head-cell:nth-child(4) .slds-th__action{
 display: flex;
 justify-content: right;
}

.serviceability-umi-table .slds-data-table-head-cell:nth-child(1){
 width: 25% !important;
}

.serviceability-umi-table .slds-data-table-head-cell:nth-child(3) ,
.serviceability-umi-table .slds-data-table-head-cell:nth-child(4) {
 width: 20% !important;
}

.serviceability-umi_help_assessed-amount,
.serviceability-umi_help_application-amount {
 position: absolute;
 z-index: 1;
}

@media screen and (min-width: 1200px){
 .serviceability-umi-table .slds-data-table-head-cell:nth-child(3) .slds-th__action > span,
 .serviceability-umi-table_income .slds-data-table-head-cell:nth-child(4) .slds-th__action > span,
 .serviceability-umi-table_debt .slds-data-table-head-cell:nth-child(4) .slds-th__action > span{
 position: relative;
 left: -22px;
 }
}
@media screen and (min-width: 2100px){
 .serviceability-umi_help_application-amount {
 top: 14px;
 right: 13.5%;
 }
 .serviceability-umi_help_assessed-amount{
 top: 14px;
 right : -6.5%
 }
}
@media screen and (min-width: 1400px) and (max-width: 2100px){
 .serviceability-umi_help_application-amount {
 top: 14px;
 right: 14.5%;
 }
 .serviceability-umi_help_assessed-amount{
 top: 14px;
 right : -5.5%
 }
}
@media screen and (min-width: 1200px) and (max-width: 1400px) {
 .serviceability-umi_help_application-amount {
 top: 14px;
 right: 15.5%;
 }
 .serviceability-umi_help_assessed-amount{
 top: 14px;
 right : -4.5%
 }
}
@media screen and (min-width: 992px) and (max-width: 1200px) {
 .serviceability-umi_help_application-amount {
 top: 0px;
 right: 20%;
 }
 .serviceability-umi_help_assessed-amount{
 top: 0px;
 right : 0%
 }
}
@media screen and (max-width: 992px) {
 .serviceability-umi_help_assessed-amount,
 .serviceability-umi_help_application-amount {
 display: none;
 }
}"}
